+  const XMMRegister one = xmm25;
+  const XMMRegister qMinus1 = xmm26;
+  const XMMRegister gamma2 = xmm27;
+  const XMMRegister twoGamma2 = xmm28;
+  const XMMRegister barrettMultiplier = xmm29;
+  const XMMRegister barrettAddend = xmm30;
