+  __ evpsubd(xmm1, k0, xmm1, xmm5, false, Assembler::AVX_512bit);
+  __ evpsubd(xmm2, k0, xmm2, xmm6, false, Assembler::AVX_512bit);
+  __ evpsubd(xmm3, k0, xmm3, xmm7, false, Assembler::AVX_512bit);
